<script>import {onMount} from 'svelte';const entries=window.PatchNotes.entries;let selected=$state(null);onMount(()=>{window.PatchNotes.markRead();window.ZonebenchShell?.({tab:'patchnotes',editor:false,version:'2.0.3',tabs:[],unread:false});});</script>
{#snippet entry(note)}<article class="patch-entry"><p class="patch-version">{note.version} · {note.date}</p><h2>{note.title}</h2><p class="patch-status">{note.status}</p><p class="page-lead">{note.summary}</p>{#each note.sections as group}<section class="patch-group"><h3>{group.title}</h3><ul>{#each group.items as text}<li>{text}</li>{/each}</ul></section>{/each}</article>{/snippet}
<p class="eyebrow">SQUARED AWAY / WHAT CHANGED</p><h1>Patch Notes</h1>{@render entry(entries[0])}<section class="patch-history"><h2>Previous updates</h2><p class="hint">Choose an update to read its patch notes.</p><div class="patch-history-tiles">{#each entries.slice(1) as note}<button class="patch-history-tile" aria-expanded={selected===note.id} onclick={()=>selected=selected===note.id?null:note.id}><span class="patch-version">{note.version}</span><strong>{note.title}</strong><span class="hint">{note.date}</span></button>{/each}</div>{#if selected}<div class="patch-history-detail"><button class="tool" onclick={()=>selected=null}>Close older notes</button>{@render entry(entries.find(n=>n.id===selected))}</div>{/if}</section><a class="tool primary" href="#help">Installation guide</a>
